use std::collections::BTreeMap;
use pathland_core::{Frame, category, component_type, tree};

#[derive(Debug, Clone, PartialEq)]
pub struct Node {
    pub component: u16,
    pub text: Option<String>,
    pub properties: BTreeMap<u16, u32>,
    pub children: Vec<u32>,
}

#[derive(Debug, Default)]
pub struct Consumer {
    nodes: BTreeMap<u32, Node>,
}

impl Consumer {
    pub fn apply(&mut self, frame: &Frame<'_>) {
        for op in frame.opcodes() {
            match op.category() {
                category::TREE => match op.command() {
                    tree::CREATE_NODE => {
                        let id = op.a();
                        let component = op.b() as u16;
                        self.nodes.insert(id, Node { component, text: None, properties: BTreeMap::new(), children: Vec::new() });
                    }
                    tree::INSERT_CHILD => {
                        let parent = op.a();
                        let child = op.b();
                        if let Some(n) = self.nodes.get_mut(&parent) {
                            n.children.push(child);
                        }
                    }
                    tree::DELETE_NODE => { self.nodes.remove(&op.a()); }
                    tree::REMOVE_CHILD => {
                        let parent = op.a();
                        let child = op.b();
                        if let Some(n) = self.nodes.get_mut(&parent) {
                            n.children.retain(|c| *c != child);
                        }
                    }
                    _ => {}
                },
                category::STYLE => {
                    // SET_TEXT: a=node, b=arenaRef; SET_PROPERTY: a=node, b=prop|vt<<16, c=value
                    ...
                }
                _ => {}
            }
        }
    }
}
```

